import React, { useState } from 'react'
import axiosInstance from '../api/axiosInstance';

export function PointsTable() {
    const [table, setTable] = useState([])
    const [tournamentId, setTournmentId] = useState()


    async function fetchPoitnsTable(e) {
        try {
            e.preventDefault()
            const response = await axiosInstance.get('/totalstats/pointstable/' + tournamentId)
            setTable(response.data.pointsTable)
            console.log(response.data.pointsTable);

        }
        catch (error) {
            console.log(error);

        }

    }



    return (
        <div>PointsTable
            <form onSubmit={fetchPoitnsTable}>
                <div>
                    <label>Tournament Id:</label>
                    <input type="text" value={tournamentId} onChange={(e) => { setTournmentId(e.target.value) }} />
                    <button>Submit</button>
                </div>
            </form>
            <div>
                {table.map((row)=>{
                    <div><p>team:{row.teams}</p></div>
                })}
            </div>


        </div>
    )
}
